// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address caller = address(0x1234);
        vm.deal(caller, 3 ether);
        // First Put: deposit 2 ether
        vm.prank(caller);
        c.Put{value: 2 ether}(block.timestamp + 100);
        // Second Put: deposit 1 ether (to trigger overflow in buggy version on Collect)
        vm.prank(caller);
        c.Put{value: 1 ether}(block.timestamp + 100);
        // Warp past unlock time
        vm.warp(block.timestamp + 200);
        // Collect 1 ether
        vm.prank(caller);
        c.Collect(1 ether);
        // Assert that balance is 1 ether (reference) vs 0 (bug)
        (uint bal,) = c.Acc(caller);
        assertTrue(bal == 1 ether);
    }
}

