pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 10 ether);
        vm.startPrank(user);
        // First Put: send 1 ether, unlockTime = block.timestamp (now)
        c.Put{value: 1 ether}(block.timestamp);
        // Second Put: send 1 ether, same unlockTime
        c.Put{value: 1 ether}(block.timestamp);
        // Now balance = 2 ether, unlockTime = block.timestamp
        // Advance time past unlockTime (simulate 1 second later)
        vm.warp(block.timestamp + 1);
        // Collect 1 ether
        c.Collect(1 ether);
        vm.stopPrank();
        // After Collect: reference contract should have 1 ether (1 ether - 0 = 1 ether)
        // Buggy contract: require true allowed overflow, balance becomes 0
        (uint balance, ) = c.Acc(user);
        assertTrue(balance == 1 ether);
    }
}

