pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up: user deposits exactly 1 ether, then warp to bypass unlockTime, and attempt to collect 2 ether (more than balance)
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.Put{value: 1 ether}(0);
        vm.warp(block.timestamp + 1000); // ensure unlockTime passed

        // Try Collect(2 ether) — reference should revert (underflow protection acc.balance >= _am fails), buggy version does not revert and underflows
        bool ok;
        vm.prank(user);
        try c.Collect(2 ether) { ok = true; } catch { ok = false; }

        // Assert that the reference reverts (ok = false) and the buggy version does not (ok = true)
        assertTrue(ok == false, "Collect should revert on reference contract");
    }
}

