        (bool okCollect2, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", 0.5 ether));

        // The assertion: in reference, the second Collect succeeds (balance was 1.0 after first collect, now 0.5)
        // In buggy, the second Collect reverts (balance stays 0)
        assertTrue(okCollect2);
    }
