pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log logContract;

    // Minimal Log interface to read History length
    interface Log {
        function History(uint) external view returns (address, string memory, uint, uint);
        function HistoryLength() external view returns (uint);
    }

    function setUp() public {
        c = new C(address(this));
        // This contract is the Log, so we can cast address(this) to Log
        logContract = Log(address(this));
    }

    function testRegression_property() public {
        // Fund the actor with 2 ether
        address actor = address(0x1);
        vm.deal(actor, 2 ether);
        vm.prank(actor);
        c.Put{value: 1 ether}(0); // deposit 1 ether, unlockTime = now

        // Warp forward to just after lock time
        vm.warp(block.timestamp + 1);

        // Now Collect the 1 ether
        vm.prank(actor);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, 1 ether));
        require(success, "Collect should succeed");

        // Reference contract logs after successful collect => History length = 1
        // Mutant does not log => History length = 0
        bool refHasLog = logContract.HistoryLength() == 1;
        assertTrue(refHasLog, "History length should be 1 after successful Collect");
    }
}

contract Log {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }

    function HistoryLength() external view returns (uint) {
        return History.length;
    }
}

