import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address alice = address(0x123);
        vm.deal(alice, 2 ether);
        vm.warp(1000);
        vm.prank(alice);
        c.Put{value: 1 ether}(500);
        vm.warp(2000);
        uint256 balanceBefore = address(c).balance;
        vm.prank(alice);
        c.Collect(1 ether);
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore - 1 ether);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up: actor puts 1 ether with unlockTime = 0 (past)
        address actor = address(0x1234);
        vm.deal(actor, 2 ether);
        vm.prank(actor);
        c.Put{value: 1 ether}(0);
        // Warp to after unlockTime (already satisfied since 0 < block.timestamp)
        vm.warp(block.timestamp + 1);
        // Record contract balance before Collect
        uint256 balanceBefore = address(c).balance;
        // Call Collect with 1 ether (amount = MinSum = 1 ether)
        vm.prank(actor);
        c.Collect(1 ether);
        uint256 balanceAfter = address(c).balance;
        // Assert that balance decreased (reference: yes; buggy: no)
        assertTrue(balanceAfter < balanceBefore, "Contract balance did not decrease after Collect");
    }
}
